  const id=r?.id||"";
  if(id==="art_lance_longinus")return{wind:"ETESIAE (MELTEMI)",weather:"DIES (Midday Radiance)",geo:"Patriarchal Devotion: +35 Fama, Clerical Allegiance",gambit:"Lancea Sancta: Ramming deals +35 Holy Damage & restores 20 Hull",nefas:-15};
  if(id==="art_true_cross")return{wind:"FAVONIUS (WEST WIND)",weather:"SERENVM (Sunlit Seas)",geo:"Holy Imperial Standard: Flagship rowers immune to panic",gambit:"Aura Vera: True holy reflection against heathen boarding",nefas:-20};
