  const omenSides = rawOmenDie.includes("20") ? 20 : rawOmenDie.includes("12") ? 12 : rawOmenDie.includes("10") ? 10 : rawOmenDie.includes("8") ? 8 : rawOmenDie.includes("4") ? 4 : 6;
  const activeOmenDieType = "D" + omenSides;

