    const eqDice = (typeof ji === "function" ? ji(playerObj) : (typeof rs !== "undefined" ? rs[0] : { material: "gold", borderColor: "#d4af37", numeralColor: "#1a1004", name: "Alea" }));
    const borderCol = eqDice.borderColor || "#d4af37";
