      const path1 = isFromPlayer ? "M 200 260 Q 500 120 800 260" : "M 800 260 Q 500 120 200 260";
      const path2 = isFromPlayer ? "M 190 235 Q 490 85 790 240" : "M 810 235 Q 510 85 210 240";
